-- ── story 9-2b: mobile pushes ──────────────────────────────────────────────
-- Generated by drizzle-kit (the queue table, the three device columns, the
-- wave alert column, the indexes) and hand-amended below the marker: the
-- CHECKs, RLS and the post-migration probe (drizzle-kit is blind to all
-- three; `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive only: one new table (written only by the notifications module),
-- three nullable columns on `devices` (tenancy — the push registration) and
-- one nullable column on `waves` (outbound — the cutoff sweep's once-per-IST-
-- date marker). No data statement — no pre-flight, no fail-fast.
CREATE TABLE "push_deliveries" (
	"tenant_id" uuid NOT NULL,
	"event_id" uuid NOT NULL,
	"device_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"tab" text NOT NULL,
	"warehouse_id" uuid,
	"approval_source" text,
	"status" text NOT NULL,
	"gateway" text,
	"error_code" text,
	"attempts" integer DEFAULT 0 NOT NULL,
	"next_attempt_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "push_deliveries_tenant_id_event_id_device_id_pk" PRIMARY KEY("tenant_id","event_id","device_id")
);
--> statement-breakpoint
ALTER TABLE "devices" ADD COLUMN "push_token" text;--> statement-breakpoint
ALTER TABLE "devices" ADD COLUMN "push_warehouse_id" uuid;--> statement-breakpoint
ALTER TABLE "devices" ADD COLUMN "push_registered_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "waves" ADD COLUMN "cutoff_risk_alerted_on" date;--> statement-breakpoint
CREATE INDEX "push_deliveries_tenant_status_next_attempt_idx" ON "push_deliveries" USING btree ("tenant_id","status","next_attempt_at");--> statement-breakpoint
CREATE INDEX "devices_push_token_idx" ON "devices" USING btree ("push_token") WHERE push_token is not null;--> statement-breakpoint
-- ── hand-amended: the controlled vocabularies (IMPLEMENTATION-GUIDE §4) ────
-- `kind`, `tab` and `status` are NOT NULL, so their bare IN arms cannot pass
-- on a NULL. `gateway` and `approval_source` are nullable: NULL is a stated,
-- intended arm (not yet sent / not an approval), and a non-null value must be
-- on the list. Pinned against the TS tuples (modules/notifications) by
-- test/push.spec.ts.
ALTER TABLE "push_deliveries" ADD CONSTRAINT "push_deliveries_kind_check" CHECK ("kind" IN ('new-work', 'approval', 'at-risk'));--> statement-breakpoint
ALTER TABLE "push_deliveries" ADD CONSTRAINT "push_deliveries_tab_check" CHECK ("tab" IN ('Pick', 'Count', 'Transfer', 'All'));--> statement-breakpoint
ALTER TABLE "push_deliveries" ADD CONSTRAINT "push_deliveries_status_check" CHECK ("status" IN ('pending', 'sending', 'sent', 'failed'));--> statement-breakpoint
ALTER TABLE "push_deliveries" ADD CONSTRAINT "push_deliveries_gateway_check" CHECK ("gateway" IS NULL OR "gateway" IN ('unconfigured', 'expo'));--> statement-breakpoint
ALTER TABLE "push_deliveries" ADD CONSTRAINT "push_deliveries_approval_source_check" CHECK ("approval_source" IS NULL OR "approval_source" IN ('stock-adjustment', 'count-variance', 'over-receipt'));--> statement-breakpoint
-- ── hand-amended: the row shape ──────────────────────────────────────────
-- (1) a new-work row carries the work's warehouse, and only a new-work row;
-- (2) an approval row carries its source, and only an approval row;
-- (3) attempts never go negative.
ALTER TABLE "push_deliveries" ADD CONSTRAINT "push_deliveries_shape_check" CHECK (
	(("kind" = 'new-work') = ("warehouse_id" IS NOT NULL))
	AND (("kind" = 'approval') = ("approval_source" IS NOT NULL))
	AND "attempts" >= 0
);--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy (the 0056/0067 shape) ────
ALTER TABLE "push_deliveries" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "push_deliveries_tenant_isolation" ON "push_deliveries"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0067 model) ────────────────────
-- The accepted shapes are inserted first and rolled back by a sentinel, so a
-- CHECK that refuses everything cannot pass. Each refused shape runs in its
-- own subtransaction and must be refused by `check_violation` ON THE NAMED
-- CONSTRAINT — a probe another CHECK happens to refuse proves nothing.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) the accepted shapes: every kind, every tab, every status, both
	-- gateways and none, every approval source.
	BEGIN
		INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","warehouse_id","approval_source","status","gateway","error_code","attempts","next_attempt_at")
		VALUES (t, gen_random_uuid(), gen_random_uuid(), 'new-work', 'Pick', t, NULL, 'pending', NULL, NULL, 0, now()),
		       (t, gen_random_uuid(), gen_random_uuid(), 'new-work', 'Count', t, NULL, 'sending', 'expo', NULL, 0, now()),
		       (t, gen_random_uuid(), gen_random_uuid(), 'new-work', 'Transfer', t, NULL, 'sent', 'unconfigured', NULL, 1, now()),
		       (t, gen_random_uuid(), gen_random_uuid(), 'approval', 'All', NULL, 'stock-adjustment', 'failed', 'expo', 'DeviceNotRegistered', 0, now()),
		       (t, gen_random_uuid(), gen_random_uuid(), 'approval', 'All', NULL, 'count-variance', 'pending', NULL, NULL, 0, now()),
		       (t, gen_random_uuid(), gen_random_uuid(), 'approval', 'All', NULL, 'over-receipt', 'pending', NULL, NULL, 0, now()),
		       (t, gen_random_uuid(), gen_random_uuid(), 'at-risk', 'All', NULL, NULL, 'failed', NULL, 'stale', 5, now());
		RAISE EXCEPTION USING ERRCODE = 'P0068', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation THEN
			RAISE EXCEPTION 'migration 0068: an accepted push delivery shape was refused.';
		WHEN SQLSTATE 'P0068' THEN
			NULL; -- the accepted shapes landed, and the sentinel rolled them back
	END;
	-- (2) the refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'unknown kind',
		'unknown tab',
		'lower-case tab',
		'unknown status',
		'unknown gateway',
		'unknown approval source',
		'new-work without a warehouse',
		'a warehouse on a non-new-work row',
		'approval without a source',
		'a source on a non-approval row',
		'negative attempts'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown kind' THEN 'push_deliveries_kind_check'
			WHEN 'unknown tab' THEN 'push_deliveries_tab_check'
			WHEN 'lower-case tab' THEN 'push_deliveries_tab_check'
			WHEN 'unknown status' THEN 'push_deliveries_status_check'
			WHEN 'unknown gateway' THEN 'push_deliveries_gateway_check'
			WHEN 'unknown approval source' THEN 'push_deliveries_approval_source_check'
			ELSE 'push_deliveries_shape_check'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown kind' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","status","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'reorder', 'All', 'pending', now());
				WHEN 'unknown tab' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","status","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'at-risk', 'Putaway', 'pending', now());
				WHEN 'lower-case tab' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","status","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'at-risk', 'all', 'pending', now());
				WHEN 'unknown status' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","status","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'at-risk', 'All', 'queued', now());
				WHEN 'unknown gateway' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","status","gateway","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'at-risk', 'All', 'sent', 'fcm', now());
				WHEN 'unknown approval source' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","approval_source","status","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'approval', 'All', 'rejected-op', 'pending', now());
				WHEN 'new-work without a warehouse' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","status","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'new-work', 'Pick', 'pending', now());
				WHEN 'a warehouse on a non-new-work row' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","warehouse_id","status","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'at-risk', 'All', t, 'pending', now());
				WHEN 'approval without a source' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","status","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'approval', 'All', 'pending', now());
				WHEN 'a source on a non-approval row' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","approval_source","status","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'at-risk', 'All', 'over-receipt', 'pending', now());
				WHEN 'negative attempts' THEN
					INSERT INTO "push_deliveries" ("tenant_id","event_id","device_id","kind","tab","status","attempts","next_attempt_at")
					VALUES (t, gen_random_uuid(), gen_random_uuid(), 'at-risk', 'All', 'pending', -1, now());
			END CASE;
		EXCEPTION WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS NULL THEN
			RAISE EXCEPTION 'migration 0068: the CHECK probe "%" was not refused.', probe;
		END IF;
		IF refused_by <> expected THEN
			RAISE EXCEPTION 'migration 0068: the CHECK probe "%" was refused by % — expected %.', probe, refused_by, expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "push_deliveries" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0068: a CHECK probe row survived.';
	END IF;
END $$;
